mapper.update:
UPDATE fbs_credit_account
SET balance = #{account.balance},
    version = #{account.version},
    last_entry_sequence = #{account.lastEntrySequence},
    last_entry_hash = #{account.lastEntryHash},
    updated_at = GREATEST(updated_at, CURRENT_TIMESTAMP(3))
WHERE account_id = #{account.accountId}
  AND user_id = #{account.userId}
  AND BINARY account_scope = BINARY #{account.accountScope}
  AND BINARY currency_code = BINARY #{account.currencyCode}
  AND version = #{expectedVersion}
  AND last_entry_sequence = #{expectedLastEntrySequence}
  AND balance = #{expectedBalance}
  AND last_entry_hash = #{expectedLastEntryHash}

UPDATE sys_user
SET points = #{nextBalance},
    update_time = NOW(3)
WHERE user_id = #{userId}
  AND del_flag = '0'
  AND COALESCE(points, 0) = #{expectedBalance}
